// 데모 토글: 기본은 true (GH Pages/시연용)
// 환경변수(REACT_APP_IS_DEMO=false)로만 끌 수 있게 함.
export const IS_DEMO =
  (process.env.REACT_APP_IS_DEMO ?? "true").toLowerCase() === "true";
